update auth.users set email='customer@example.invalid' where id='00000000-0000-4000-8000-000000000003';
update public.customer_access set can_approve=true where user_id='00000000-0000-4000-8000-000000000003';
insert into public.contacts(organization_id,id,customer_id,name,email,phone,relationship) values('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Synthetic Customer','customer@example.invalid','5550000000','self');
insert into public.properties(organization_id,id,customer_id,street,city,region) values('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','100 Synthetic Street','DeKalb','IL'),('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000002','200 Other Street','DeKalb','IL');
insert into public.catalog_services(organization_id,name,pricing_mode,scope,exclusions) values('20000000-0000-4000-8000-000000000001','Yard & garden','hourly','Synthetic scope','Synthetic limits');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000003","session_id":"10000000-0000-4000-8000-000000000003","aal":"aal1"}',true);
select pg_temp.assert_true(jsonb_array_length(public.customer_intake_context('20000000-0000-4000-8000-000000000001')->'properties')=1,'only explicitly linked property exposed');
select public.submit_customer_request('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','repeat-request-key-0001','{"services":[{"service":"Lawn care","task":"Mowing"},{"service":"Yard & garden","task":"Pulling weeds by hand"}],"description":"","preferredTime":"Next week","communityRate":"No"}');
select public.submit_customer_request('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','repeat-request-key-0001','{"services":[{"service":"Lawn care","task":"Mowing"},{"service":"Yard & garden","task":"Pulling weeds by hand"}],"description":"","preferredTime":"Next week","communityRate":"No"}');
select pg_temp.assert_true((select count(*)=1 from public.service_requests),'one linked request on retry');
select pg_temp.assert_true((select count(*)=2 from public.service_request_items),'both category jobs retained');
select pg_temp.assert_true((select original_submission->>'name'='Synthetic Customer' and original_submission->>'street'='100 Synthetic Street' from public.service_requests),'contact fields from stored records only');
do $$begin begin perform public.submit_customer_request('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000003','repeat-unrelated-0001','{}');raise exception 'TEST FAILED unrelated address';exception when insufficient_privilege then null;end;end$$;
do $$begin begin perform public.customer_intake_context('20000000-0000-4000-8000-000000000002');raise exception 'TEST FAILED other tenant';exception when insufficient_privilege then null;end;end$$;
do $$begin begin perform public.submit_customer_request('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','repeat-request-key-0001','{"services":[{"service":"Lawn care","task":"Mowing"}],"description":"Changed work","preferredTime":"Next week","communityRate":"No"}');raise exception 'TEST FAILED edited retry';exception when raise_exception then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;end$$;
do $$begin begin perform public.submit_customer_request('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','repeat-forged-details-01','{"name":"Forged","services":[{"service":"Lawn care","task":"Mowing"}],"description":"","preferredTime":"","communityRate":"No"}');raise exception 'TEST FAILED contact overwrite';exception when raise_exception then if sqlerrm<>'VALIDATION' then raise;end if;end;end$$;
reset role;
select pg_temp.assert_true((select count(*)=1 from public.outbox),'one owner notice committed');
select pg_temp.assert_true((select count(*)=1 from public.audit_events where actor_id='00000000-0000-4000-8000-000000000003'),'customer actor audited');
update public.contacts set phone='5551111111';
set local role authenticated;
select public.submit_customer_request('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','repeat-request-key-0001','{"services":[{"service":"Lawn care","task":"Mowing"},{"service":"Yard & garden","task":"Pulling weeds by hand"}],"description":"","preferredTime":"Next week","communityRate":"No"}');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.service_requests),'contact change does not duplicate retry');
update public.customer_access set revoked_at=now() where user_id='00000000-0000-4000-8000-000000000003';
set local role authenticated;
do $$begin begin perform public.customer_intake_context('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED revoked relationship';exception when insufficient_privilege then null;end;end$$;
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','public.submit_customer_request(uuid,uuid,uuid,text,jsonb)','EXECUTE'),'anonymous repeat intake denied');
rollback;
